package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class WebauthnRpIdVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property webauthn rp id of tenant config ")
  void test_webauthn_rp_id_v_o_builder() {
    Assertions.assertFalse(WebauthnRpIdVO.nullValue().getWebauthnRpId().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(WebauthnRpIdVO.tryFrom(null).getWebauthnRpId().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", WebauthnRpIdVO.from("one").getWebauthnRpId().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> WebauthnRpIdVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", WebauthnRpIdVO.from("one").toString());
  }
}
